//! What the typed operations of a flow (`add`, `toInt32`, `newUuid`...) call. A flaw of the flow, an overflow or a
//! division by zero, is an internal error (500, logged): never a silent wrap-around.
//!
//! @generated by service-builder. Do not edit: changes are overwritten on the next export.

use anyhow::{Result, anyhow};

/// The result of a checked integer operation, or the error of the operation that failed.
pub fn checked<T>(value: Option<T>, operation: &str) -> Result<T> {
    value.ok_or_else(|| anyhow!("`{operation}`: integer overflow or division by zero"))
}

/// A float as an int64: rounded by the caller, refused when it is not a number or does not fit.
pub fn f64_to_i64(value: f64) -> Result<i64> {
    // 2^63 is the first float above i64::MAX, and it is exact.
    if value.is_finite() && value >= -9_223_372_036_854_775_808.0 && value < 9_223_372_036_854_775_808.0 {
        Ok(value as i64)
    } else {
        Err(anyhow!("{value} does not fit an int64"))
    }
}

/// An int64 as a narrower integer, refused when it does not fit.
pub fn int<T: TryFrom<i64>>(value: i64) -> Result<T> {
    T::try_from(value).map_err(|_| anyhow!("{value} does not fit the target integer type"))
}

pub fn new_uuid() -> String {
    uuid::Uuid::new_v4().to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn overflow_and_division_by_zero_fail() {
        assert_eq!(checked(i32::checked_add(1, 2), "add").unwrap(), 3);
        assert!(checked(i32::checked_add(i32::MAX, 1), "add").is_err());
        assert!(checked(i64::checked_div(1, 0), "div").is_err());
        assert!(checked(i64::checked_rem(1, 0), "rem").is_err());
        assert!(checked(i64::checked_div(i64::MIN, -1), "div").is_err());
    }

    #[test]
    fn conversions_refuse_what_does_not_fit() {
        assert_eq!(f64_to_i64(2.5_f64.round()).unwrap(), 3);
        assert_eq!(f64_to_i64((-2.5_f64).round()).unwrap(), -3);
        assert!(f64_to_i64(f64::NAN).is_err());
        assert!(f64_to_i64(1e300).is_err());
        assert!(f64_to_i64(9_223_372_036_854_775_808.0).is_err());
        assert_eq!(int::<i32>(7).unwrap(), 7);
        assert!(int::<i32>(i64::MAX).is_err());
    }

    #[test]
    fn uuids_are_new_and_well_formed() {
        let (a, b) = (new_uuid(), new_uuid());
        assert_ne!(a, b);
        assert_eq!(a.len(), 36);
    }
}
